def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    # Begin very politely; a few early rounds are not worth risking cycles.
    if n <= 4:
        return 'C'

    opp_c = 0
    my_d = 0
    for m, o in history:
        if o == 'C':
            opp_c += 1
        if m == 'D':
            my_d += 1

    opp_rate = opp_c / n

    last_me, last_opp = history[-1]

    w = 10 if n >= 10 else n
    recent_opp_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
    recent_rate = recent_opp_c / w

    tail_opp_d = 0
    if last_opp == 'D':
        for _, o in reversed(history):
            if o == 'D':
                tail_opp_d += 1
            else:
                break

    tail_mutual_c = 0
    for m, o in reversed(history):
        if m == 'C' and o == 'C':
            tail_mutual_c += 1
        else:
            break

    # exploit means: the most recent known response to one of our defections
    # was cooperation, and the original defection round was also cooperative
    # for the opponent. In that case the opponent is safe to keep exploiting.
    exploit = False
    for i in range(n - 1, 0, -1):
        if history[i - 1][0] == 'D':
            exploit = (history[i - 1][1] == 'C' and history[i][1] == 'C')
            break

    # Defect against clearly hostile opponents.
    if recent_rate < 0.2:
        return 'D'
    if opp_rate < 0.25:
        return 'D'

    # Keep exploiting a cooperative, forgiving opponent.
    if exploit and recent_rate > 0.5 and last_opp == 'C':
        return 'D'

    # After a single probe or a mutual-defection round, try to learn / repair
    # rather than creating a retaliation cycle.
    if last_me == 'D':
        if recent_rate > 0.6 or opp_rate > 0.8:
            return 'C'
        return 'D'

    # Opponent just defected. Forgive one isolated defection by a cooperative
    # opponent, then punish repeated defection.
    if last_opp == 'D':
        if tail_opp_d <= 1 and recent_rate > 0.7 and opp_rate > 0.7:
            return 'C'
        return 'D'

    # A careful first exploratory defection against stable cooperation.
    # The next round is forced to 'C' above, allowing us to learn whether the
    # opponent forgives. If it does, the exploit rule activates afterward.
    if (
        my_d == 0
        and 25 <= n <= 85
        and tail_mutual_c >= 20
        and opp_rate > 0.8
        and recent_rate > 0.8
    ):
        return 'D'

    # One second exploratory defection if the first was punished but long,
    # clean cooperation has returned. This can recover a forgiving partner.
    if (
        my_d == 1
        and 50 <= n <= 85
        and tail_mutual_c >= 30
        and opp_rate > 0.9
        and recent_rate > 0.95
    ):
        return 'D'

    # Late game: do not stay soft with a recently uncooperative opponent.
    if n > 85 and recent_rate < 0.5 and opp_rate < 0.6:
        return 'D'

    return 'C'
